from pathlib import Path
p=Path('index.html'); s=p.read_text(encoding='utf-8')
css='''<style id="mobile-readability-v2">\n@media(max-width:600px){\n  body{font-size:14px!important;-webkit-text-size-adjust:100%}\n  .label{font-size:11px!important;line-height:1.25!important}\n  .value{font-size:21px!important;line-height:1.15!important}\n  .section h2{font-size:16px!important;line-height:1.25!important;margin:9px 2px 7px!important}\n  .sub{font-size:10px!important}.pill{font-size:10px!important}\n  .cue b,.row b{font-size:13px!important}.status,.age,.tip{font-size:12px!important;line-height:1.45!important}\n  .intel-title{font-size:13px!important}.intel-line{font-size:11px!important;line-height:1.4!important}.intel-muted{font-size:10px!important}.intel-badge{font-size:10px!important}\n  .swing-v2 h3{font-size:14px!important}.swing-headmeta{font-size:10px!important}.swing-symbol{font-size:16px!important}.swing-action{font-size:10px!important}.swing-life{font-size:9px!important}.swing-meta{font-size:11px!important}.swing-k small{font-size:9px!important}.swing-k b{font-size:12px!important}.swing-confirm{font-size:10px!important;line-height:1.4!important}.swing-actions button,.swing-share{font-size:10px!important;padding:8px!important}\n  .os-chip{font-size:10px!important}.os-chip b,.os-plan b{font-size:12px!important}.os-chip span,.os-plan span{font-size:9px!important}.os-reason{font-size:10px!important}\n  .nav span{font-size:9px!important}.nav b{font-size:17px!important}\n}\n.stock-search{margin:5px 7px 8px;padding:10px;background:#fff;border:1px solid #d8e2ed;border-radius:13px;box-shadow:0 3px 10px rgba(16,33,59,.05)}.stock-search-row{display:grid;grid-template-columns:1fr 92px;gap:7px}.stock-search input{width:100%;padding:11px 12px;border:1px solid #cbd8e5;border-radius:10px;font-size:14px;font-weight:700;outline:none;color:#10213b;background:#f8fafc}.stock-search input:focus{border-color:#087dca;box-shadow:0 0 0 2px #087dca20}.stock-search button{border:0;border-radius:10px;background:#087dca;color:#fff;font-weight:900;font-size:12px;cursor:pointer;touch-action:manipulation}.stock-search-help{font-size:10px;color:#718198;margin-top:6px}.stock-result{margin-top:8px;padding:10px;border:1px solid #dce5ef;border-radius:10px;background:#f8fafc}.stock-result-head{display:flex;justify-content:space-between;gap:8px;align-items:center}.stock-result-symbol{font-size:16px;font-weight:950}.stock-result-action{font-size:10px;font-weight:900;padding:4px 7px;border-radius:999px}.stock-result-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:7px}.stock-result-grid div{background:#fff;border:1px solid #e1e8ef;border-radius:7px;padding:6px;text-align:center}.stock-result-grid small{display:block;font-size:8px;color:#718198}.stock-result-grid b{font-size:11px}.stock-result-meta{font-size:10px;line-height:1.45;color:#52647a;margin-top:7px}.stock-result-actions{display:flex;gap:6px;margin-top:7px}.stock-result-actions button{flex:1;padding:8px;border-radius:8px;border:1px solid #d6e1eb;background:#fff;color:#0b2a52;font-weight:850;font-size:10px}.stock-error{color:#c3314a;font-weight:800;font-size:11px;padding-top:7px}\n</style>'''
if 'id="mobile-readability-v2"' not in s:s=s.replace('</head>',css+'</head>',1)
panel='''<div class="stock-search" id="stockSearchPanel"><div class="stock-search-row"><input id="stockSearchInput" type="search" inputmode="text" autocomplete="off" autocapitalize="characters" placeholder="Search NIFTY 500 stock (RELIANCE, TCS…)" aria-label="Search NIFTY 500 stock"><button id="stockAnalyzeBtn" type="button">🔎 ANALYZE</button></div><div class="stock-search-help">Swing analysis: Daily/Weekly trend • breakout/pullback • volume • relative strength • SMC • risk plan</div><div id="stockSearchResult"></div></div>'''
if 'id="stockSearchPanel"' not in s:
    marker='<div class="section"><h2>🎯 Sniper Verdict</h2>'
    if marker in s:s=s.replace(marker,panel+'\n'+marker,1)
    else:s=s.replace('</main>',panel+'</main>',1)
js='''<script id="stock-search-js">(function(){const input=document.getElementById('stockSearchInput'),btn=document.getElementById('stockAnalyzeBtn'),box=document.getElementById('stockSearchResult');if(!input||!btn||!box)return;function esc(v){return String(v==null?'—':v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function cls(a){return String(a||'WAIT').toLowerCase()}function share(x){return encodeURIComponent(`📈 NIFTY Sensex Sniper — Stock Swing Analysis\\n${x.symbol||'—'} | ${x.action||'WAIT'} | Score ${x.score||0}/10\\nSetup: ${x.setup||'—'} | Holding: ${x.holding_period||'—'}\\nEntry: ${x.entry??'—'} | SL: ${x.stoploss??'—'} | T1: ${x.target1??'—'} | T2: ${x.target2??'—'}\\nR:R: ${x.rr||'—'} | Invalidation: ${x.invalidation||'—'}\\nEducational/probabilistic only.`)}async function run(){const q=input.value.trim().toUpperCase();if(q.length<2){box.innerHTML='<div class="stock-error">Stock symbol enter karein — e.g. RELIANCE, TCS, INFY.</div>';return}btn.disabled=true;btn.textContent='⏳ ANALYZING';box.innerHTML='<div class="stock-result-meta">Live NIFTY 500 swing analysis chal raha hai…</div>';try{const d=await(await fetch('/api/stock-analysis?symbol='+encodeURIComponent(q)+'&ts='+Date.now(),{cache:'no-store'})).json();if(!d.ok||!d.result){box.innerHTML='<div class="stock-error">⚠️ '+esc(d.error||'Analysis unavailable. No fallback guess generated.')+'</div>';return}const x=d.result;const conf=(x.confirmations||[]).slice(0,5).map(esc).join(' • ')||'Confirmation pending';box.innerHTML=`<div class="stock-result"><div class="stock-result-head"><span class="stock-result-symbol">${esc(x.symbol)}</span><span class="stock-result-action ${cls(x.action)}">${esc(x.action)} • ${esc(x.score)}/10</span></div><div class="stock-result-meta">${esc(x.setup)} • ${esc(x.lifecycle)} • ⏳ ${esc(x.holding_period)} • ₹${esc(x.current_price)}</div><div class="stock-result-grid"><div><small>ENTRY</small><b>${esc(x.entry)}</b></div><div><small>SL</small><b>${esc(x.stoploss)}</b></div><div><small>T1</small><b>${esc(x.target1)}</b></div><div><small>R:R</small><b>${esc(x.rr)}</b></div></div><div class="stock-result-meta">🧩 ${conf}<br>📊 Trend ${esc(x.trend)} • Volume ${esc(x.volume)} • RS ${esc(x.relative_strength_pct)}%<br>🧠 SMC ${esc(x.smc?.status)} • BOS ${esc(x.smc?.bos)}</div><div class="stock-result-actions"><button type="button" id="saveStockBtn">👁️ WATCHLIST</button><a class="swing-share wa" target="_blank" rel="noopener" href="https://wa.me/?text=${share(x)}">📲 WHATSAPP</a></div></div>`;document.getElementById('saveStockBtn')?.addEventListener('click',()=>{try{const a=JSON.parse(localStorage.getItem('sniperWatchlist')||'[]').filter(v=>(typeof v==='string'?v:v.symbol)!==x.symbol);a.push({symbol:x.symbol,lifecycle:x.lifecycle,entry:x.entry,stoploss:x.stoploss,target1:x.target1,target2:x.target2,current_price:x.current_price,saved_at:new Date().toISOString()});localStorage.setItem('sniperWatchlist',JSON.stringify(a));document.getElementById('saveStockBtn').textContent='✓ SAVED'}catch(e){}})}catch(e){box.innerHTML='<div class="stock-error">⚠️ Network/analysis error. Please try again.</div>'}finally{btn.disabled=false;btn.textContent='🔎 ANALYZE'}}btn.addEventListener('click',run);input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();run()}})})();</script>'''
if 'id="stock-search-js"' not in s:s=s.replace('</body>',js+'</body>',1)
p.write_text(s,encoding='utf-8')
